questionvariables.text:
/* Design: extends the Grade 11 graphical derivative. Kind "Q": f' = c0(x-u0)(x-w0); kind "D": f' = c0(x-u0)^2(x-w0), which touches the axis at u0 (a point of inflection of f). Source: original. */
L: [["Q",1,-2,1],["D",1,1,-2],["Q",-1,-1,3],["D",-1,-1,2],["Q",1,0,4],["D",1,2,-1],["Q",-1,-3,1],["D",-1,0,3],["Q",1,-1,2],["D",1,-2,1]];
ix: 1+rand(10);
kd: L[ix][1]; c0: L[ix][2]; u0: L[ix][3]; w0: L[ix][4];
gp: if kd="Q" then c0*(x-u0)*(x-w0) else c0*(x-u0)^2*(x-w0);
s1: min(u0,w0); s2: max(u0,w0);
xv: if kd="Q" then (u0+w0)/2 else (u0+2*w0)/3;
ga: ev(gp,x=s1-1/2); gb: ev(gp,x=(s1+s2)/2); gc: ev(gp,x=s2+1/2);
n1: (if ga>0 and gb<0 then 1 elseif ga<0 and gb>0 then 2 else 3);
n2: (if gb>0 and gc<0 then 1 elseif gb<0 and gc>0 then 2 else 3);
tch: if kd="D" then u0 else 1000;
nat2: [["max2",is(n1=1),"maximum point"],["min2",is(n1=2),"minimum point"],["inf2",is(n1=3),"point of inflection"]];
wa2: if n1=1 then "min2" else "max2";
wb2: if n1=3 then "min2" else "inf2";
nat4: [["max4",is(n2=1),"maximum point"],["min4",is(n2=2),"minimum point"],["inf4",is(n2=3),"point of inflection"]];
wa4: if n2=1 then "min4" else "max4";
wb4: if n2=3 then "min4" else "inf4";

/* board window */
xl: s1-2; xr: s2+2;
yl: min(ev(gp,x=xl),ev(gp,x=xr),ev(gp,x=xv),-1); yu: max(ev(gp,x=xl),ev(gp,x=xr),ev(gp,x=xv),1);
yl: max(yl,-12); yu: min(yu,12); pd: (yu-yl)/10;
kdD: if kd="D" then 1 else 0;
